            let mut current = WorkCounter::new(limit);
            current.allocation = Some(&payer);
            let before = original::live_nodes(&cfg, LoanId(0), 0, &seeds, &reachable, &mut old);
            let mut pending = Vec::new();
            let actual = live_nodes_with_pending(
