                    &mut drafts,
                    PaidDraft {
                        site: expression.id.clone(),
                        origin: storage::clone_place(&origin, payer)?,
                        origin_span: scrutinee.span,
                        parent_root: aliases
                            .contains_key(&place.root)
                            .then(|| place.root.clone()),
                        binding: None,
